mapper.select:
SELECT osm_id, layer, sub_type AS subtype, COALESCE(name, '') AS name, ST_X(ST_PointOnSurface(geom)) AS lon, ST_Y(ST_PointOnSurface(geom)) AS lat FROM osm_feature WHERE ( name ILIKE #{pattern} ESCAPE '!' OR sub_type ILIKE #{pattern} ESCAPE '!' )
AND layer = #{layer}
ORDER BY CASE WHEN name ILIKE #{pattern} ESCAPE '!' THEN 0 ELSE 1 END, length(COALESCE(name, sub_type)) LIMIT #{limit}
